from module_adapters._graph_extended_support import Diagram,validate
SOURCE='appnp-modules/src/appnp_layer.py';KEY='appnp_propagation'
LINKS=[('h0','step.spmm','state0','initial_state'),('edges','drop','in','topology'),('edges','step.spmm','indices','topology'),('drop','step.spmm','weights','topology'),('step.spmm','scale','in','tensor'),('scale','add','propagated','tensor'),('h0','restart','in','retained_value'),('restart','add','restart','tensor'),('add','step.spmm','state_next','loop_recurrence'),('add','output','in','tensor')]
REQUIRED={'step.spmm':dict(opaque_runtime_boundary=True,expression='spmm(index=self.edge_indices, value=edge_weights, n=localized_predictions.shape[0], m=localized_predictions.shape[0], matrix=localized_predictions)'), 'restart':dict(expression='self.args.alpha * latent_features_2'),'scale':dict(expression='(1-self.args.alpha)*new_features'),'drop':dict(resampled_inside_loop=False)}
CONTRACTS=[('APPNPModel.forward','(1-self.args.alpha)*new_features'),('APPNPModel.forward','self.args.alpha*latent_features_2'),('APPNPModel.forward','range(self.args.iterations)')]
def build():
 d=Diagram(KEY,'APPNP restart propagation',SOURCE,'APPNPModel.forward','Approximate branch only: latent_features_2 boundary through localized_predictions; excludes both feature MLP layers and final log_softmax.',dict(alpha=.1,iterations=3,model='approximate',display='APPNP iteration template / alpha=.1 / K=3 / no task head',edge_dropout_once_per_forward=True,shared_fixed_restart=True))
 d.input('h0','Retained initial H0','[N,8]',boundary='latent_features_2');d.input('edges','Sparse topology / weights','indices[2,E], values[E]',kind='control')
 d.node('drop','Edge weight Dropout / once','dropout','[E]',0,resampled_inside_loop=False,training='caller mode',p='self.args.dropout')
 d.stage('step','Repeat K=3 / sparse propagation','[N,8]',1,[('spmm','A_drop @ current H','spmm','[N,8]',dict(opaque_runtime_boundary=True,expression=REQUIRED['step.spmm']['expression']))],suppress_input_boundary=True,iteration_template=True,repeat=3,parameter_sharing='same topology/dropout sample across all iterations')
 d.node('scale','Scale propagated state by 1-alpha','multiply','[N,8]',2,expression='(1-self.args.alpha)*new_features');d.node('restart','Scale SAME H0 by alpha','multiply','[N,8]',2,expression='self.args.alpha * latent_features_2')
 d.node('add','Add restart to propagated state','add','[N,8]',3,expression='localized_predictions + self.args.alpha*latent_features_2')
 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='right' if p=='indices' else 'left' if r in ('retained_value','loop_recurrence') else 'out',ds='right' if p=='indices' else 'left' if r=='loop_recurrence' else 'in',sp='indices' if p=='indices' else 'values' if s=='edges' else 'out')
 return d.build(d.entry,'[N,8]','APPNPPropagation.md',['One representative recurrence is shown with K=3 declared example repeats. Feedback edges carry next H, not fresh task logits.','Edge Dropout occurs before the loop and is shared within a forward. Restart is always the same latent_features_2, never the latest H.','Normalized topology is external at the chosen module boundary; torch_sparse.spmm remains a library boundary.'],['Do not put log_softmax or the predictor MLP inside this propagation module.','Do not resample edge dropout each iteration or use alpha*H_t as restart.'])
SOURCE_PORTS=[('edges','drop','in','values'),('edges','step.spmm','indices','indices')]
def validate_ir(ir):return validate(ir,KEY,REQUIRED,LINKS,dict(shared_fixed_restart=True,edge_dropout_once_per_forward=True),SOURCE_PORTS)
